head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gIdx_cmb_MBR_ID = 0;
scwin.gLdMktTp = js_market;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    await scwin.getListExturePlusMbrId();
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (js_market === "9") {
        rdo_MKT_ID.Enable = true;
        rdo_MKT_ID.ClassName = "TopCondition_Blue";
    } else {
        // 콘트롤 잠그기
        rdo_MKT_ID.Enable = false;
    }
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '6') {
        // grd_Grid.ColumnProp("SPOT_ISU_TRD_MKT_TP_CD_NM", "Show") = false;
        panel_mkt.hide();
    }
};

/**
 * @method
 * @name setHeader
 * @description 저장용
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    // 저장용
    await scwin.init1();
    // 삭제용
    await scwin.init2();
};

/**
 * @method
 * @name init1
 * @description ********************************************************************
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init1 = async function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    const sbmOptions = {
        id : "sbm_dts_info",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_info.AddRow(); /*ORG SRC: dts_info.NameString(1, "EXTUREPLUS_MBR_ID") = ""; //안하면 헤더생성안됨*/ X = ""; // 안하면 헤더생성안됨

};

/**
 * @method
 * @name init2
 * @description ********************************************************************
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init2 = async function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    const sbmOptions = {
        id : "sbm_dts_del",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_del=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_del.AddRow(); /*ORG SRC: dts_del.NameString(1, "EXTUREPLUS_MBR_ID") = ""; //안하면 헤더생성안됨*/ X = ""; // 안하면 헤더생성안됨

};

/**
 * @method
 * @name getListExturePlusMbrId
 * @description get List Exture Plus Mbr Id 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getListExturePlusMbrId = async function() {
    const sbmOptions = {
        id : "sbm_dts_id",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_id=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name reload
 * @description reload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reload = async function() {
    scwin.gIdx_cmb_MBR_ID = cmb_EXTUREPLUS_MBR_ID.Index;
    await scwin.setCode(); // 콤보박스 코드 조회 후 내역을 조회하도록 함(이전 선택된 콤보값을 확인하기 위해)

};

/**
 * @method
 * @name reloadForPopup
 * @description reload For Popup 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reloadForPopup = async function() {
    cmb_EXTUREPLUS_MBR_ID.Index = scwin.gIdx_cmb_MBR_ID;
    await scwin.search();
    await scwin.setHeader();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&MKT_ID=" + rdo_MKT_ID.getValue();
    url += "&EXTUREPLUS_MBR_ID=" + cmb_EXTUREPLUS_MBR_ID.getValue();
    url += "&CHRG_NM=" + srch_CHRG_NM.getValue();
    url += "&SCREN_ID=" + "ULDSTF30378.gfm";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name searchDtl
 * @description search Dtl 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDtl = async function(row) {

    url += "&NMLIST_SEQ=" + dts_MASTER.NameString(row, "NMLIST_SEQ");
    url += "&SCREN_ID=" + "ULDSTF30378.gfm";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_info",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name new
 * @description new 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.new = async function() {
    await scwin.init1();
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    /*
    if(getObjectValue(txb_EXTUREPLUS_MBR_NM) == '') {
    	alert("[회원사명]을 입력하세요." );

    	txb_EXTUREPLUS_MBR_NM.focus();
    	return;
    }
    if(getObjectValue(txb_DEP_NM) == '') {
    	alert("[소속부서]를 입력하세요." );

    	txb_DEP_NM.focus();
    	return;
    }
    if(getObjectValue(txb_TEL_NO) == '') {
    	alert("[전화번호(회사)]를 입력하세요." );

    	txb_TEL_NO.focus();
    	return;
    }
    if(getObjectValue(txb_JOBTITL_NM) == '') {
    	alert("[직급]을 입력하세요." );

    	txb_JOBTITL_NM.focus();
    	return;
    }
     */
    if (txb_CHRG_NM.getValue() === '') {
        alert("[성명]을 입력하세요.");

        txb_CHRG_NM.focus();
        return;
    }
    if (txb_CELLPHONE_NO.getValue() === '') {
        alert("[휴대전화번호]를 입력하세요.");

        txb_CELLPHONE_NO.focus();
        return;
    }
    let regExpTel = /^0(?:\d{1}|\d{2})-(?:\d{3}|\d{4})-\d{4}$/; // 정규식 체크 - 전화번호
    const regExpCell = /^01(?:0|1|[6-9])-(?:\d{4})-\d{4}$/; // 정규식 체크 - 휴대폰번호

    if (!regExpTel.test(txb_TEL_NO.getValue()) && txb_TEL_NO.getValue() !== '') {
        alert("[전화번호(회사)]를 확인해 주세요.");

        txb_TEL_NO.focus();
        return;
    }
    if (!regExpCell.test(txb_CELLPHONE_NO.getValue())) {
        alert("[휴대전화번호]를 확인해 주세요.");

        txb_CELLPHONE_NO.focus();
        return;
    }
    if (confirm('저장 하시겠습니까?')) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        gLastJob = "저장"; /*ORG SRC: dts_info.NameValue(1, "EMP_NO") = js_emp_no;*/ X = js_emp_no; /*ORG SRC: dts_info.NameValue(1, "LD_MKT_TP_CD") = js_market;*/ X = js_market;
        trs_Save.KeyName = "toinb_dataid4";

        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/NoteMgt.do",
            ref : "dts_info",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
$c.lce.fn_checkPhoneNumber = function(obj) {
    const text = obj.getValue().replace(/-/g, "");
    let regExpTel = /(^02.{0}|^01.{1}|[0-9]{3})([0-9]+)([0-9]{4})/; // 정규식 체크 - 전화번호

    obj.setValue(text.replace(regExpTel, "$1-$2-$3"));
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(row) {
    if (confirm('삭제 하시겠습니까?')) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        gLastJob = "삭제"; /*ORG SRC: dts_del.NameString(1, "NMLIST_SEQ") = dts_MASTER.NameString(row, "NMLIST_SEQ");*/ X = dts_MASTER.NameString(row, "NMLIST_SEQ"); /*ORG SRC: dts_del.NameString(1, "EMP_NO") = js_emp_no;*/ X = js_emp_no;
        trs_Save.KeyName = "toinb_dataid4";

        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/NoteMgt.do",
            ref : "dts_del",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e) {
    await scwin.reload();
};

/**
 * @method
 * @name dts_MASTER_OnFail
 * @description MASTER On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnFail = async function() {
    await $c.win.alert(dts_MASTER);
};

/**
 * @method
 * @name dts_MASTER_OnLoadError
 * @description dts_MASTER 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadError = async function() {
    await $c.win.alert(dts_MASTER);
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {

        dts_MASTER.ClearData();
    }

};

/**
 * @method
 * @name dts_id_OnLoadError
 * @description dts_id 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_id_OnLoadError = async function() {
    await $c.win.alert(dts_info);
};

/**
 * @method
 * @name dts_id_OnLoadCompleted
 * @description dts_id 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_id_OnLoadCompleted = async function(rowcount) {
    cmb_EXTUREPLUS_MBR_ID.Index = scwin.gIdx_cmb_MBR_ID;
    await scwin.search();
    await scwin.setHeader();
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {

    alert_error2(trs_Save);
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    const msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
    alert(msg);
    await scwin.reload();
};

/**
 * @method
 * @name btn_Upload_onclick
 * @description 「엑셀업로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Upload_onclick = function(e) {

    const options = {
        id: "ULDSTF30379",
        title: "엑셀 업로드",
        type: "browserPopup",
        width: "100px",
        height: "100px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/bizspt/ULDSTF30379.gfm", options);
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function(e) {
    $c.stf.doLogSave("ULDSTF30378.gfm", SCREN_PROCS_TP_CD_07, '');
    const file_name = "회원사 비상연락망 명부";
    const today = $c.ut.cGetToday('yyyymmddhhmmss');
    const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xls";

    grd_Grid.GridToOffice(file_name, xls_path, "8", 0);
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    await scwin.searchDtl(row);
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid === "DEL_YN") {
        await scwin.delete(row);
    }
};

/**
 * @method
 * @name btn_Init_onclick
 * @description 「초기화」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Init_onclick = async function(e) {
    await scwin.new();
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
