};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.libRoundPanel.PanelToGroupBox(panel_2);
    scwin.init();
    await scwin.setCode();
    await scwin.setHeader();

    // fn_Search();

};

